LINE = [(0, 4), (1, 3), (2, 2), (3, 1), (4, 0)]

def best(b):
    m = 0
    for s in (0, 1):
        w = LINE[s:s + 4]
        if any(b.grid[r][c] == 1 for (r, c) in w):
            continue
        n = sum(1 for (r, c) in w if b.grid[r][c] == 2)
        m = max(m, n)
    return m

def fires(b):
    return best(b) >= 2

def level(b):
    n = best(b)
    return [0, 1, 6, 9, 9][n]

HOT = {(2, 1): 3, (2, 2): 3, (3, 1): 2, (1, 3): 1, (2, 0): 1, (4, 0): 1, (1, 1): 1}

def nbrs(b, r, c):
    n = 0
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            if dr == 0 and dc == 0:
                continue
            rr, cc = r + dr, c + dc
            if 0 <= rr < 6 and 0 <= cc < 7 and b.grid[rr][cc] == 2:
                n += 1
    return n

def score(b):
    if b.last_col is None:
        return 0
    cell = (b.last_row, b.last_col)
    w = HOT.get(cell, 0)
    if w == 0:
        return 0
    return w + nbrs(b, cell[0], cell[1])

def fires(b):
    return score(b) >= 5

def level(b):
    return min(9, max(0, 2 * (score(b) - 3)))

def bad_cols(b):
    if b.my_playable_wins:
        return 0
    blocks = set(c for (r, c) in b.their_playable_wins)
    bad = set()
    for c in b.legal:
        r = b.landing(c)
        if blocks and c not in blocks:
            bad.add(c)
        elif len(blocks) > 1:
            bad.add(c)
        elif (r + 1, c) in b.their_wins:
            bad.add(c)
    return len(bad)

def fires(b):
    return bad_cols(b) >= 4

def level(b):
    n = bad_cols(b)
    return [0, 1, 2, 3, 6, 8, 9, 9][n]

